5	
6	/**
7	 * 读接口与写接口响应体集合。时间字段均为 UTC ISO-8601。
8	 */
9	public final class Responses {
10	
11	    private Responses() {
12	    }
13	
14	    /** 事件当前视图：pendingTransferTo 为待接受的交接目标人，无则 null。 */
15	    public record IncidentView(String incidentKey, String severity, String summary, String reporter,
16	                               String status, String commander, String pendingTransferTo,
17	                               Instant createdAt, Instant updatedAt, Instant deadlineAt) {
18	    }
19	
20	    /** 交接单视图。 */
21	    public record TransferView(long id, String fromCommander, String toCommander,
22	                               String status, Instant createdAt, Instant acceptedAt) {
23	    }
24	
25	    /** 处置记录视图。 */
26	    public record ActionView(String actionKey, String actionType, String note,
27	                             Instant occurredAt, String actor, Instant createdAt) {
28	    }
29	
30	    /** 状态流转历史视图：fromStatus 在创建记录中为 null。 */
31	    public record StatusChangeView(String fromStatus, String toStatus, String actor, Instant occurredAt) {
32	    }
33	
34	    /**
35	     * 遏制逾期升级记录视图：deadlineAt 为接管时确定的遏制期限（UTC）；
36	     * triggeredAt 为触发时刻；note/acknowledgedBy/acknowledgedAt 仅 ACKNOWLEDGED 有值。
37	     */
38	    public record EscalationView(Long id, Instant deadlineAt, Instant triggeredAt,
39	                                 String triggeredCommander, String status, String note,
40	                                 String acknowledgedBy, Instant acknowledgedAt, Instant createdAt) {
41	    }
42	
43	    /** 完整历史：事件本体 + 状态流转 + 处置记录 + 交接记录 + 升级记录。 */
