                        .content("{\"requestId\":\"" + key() + "\","
                                + "\"tasks\":[{\"taskId\":\"A\",\"title\":\"a\"},"
                                + "{\"taskId\":\"B\",\"title\":\"b\"}],"
                                + "\"edges\":[{\"fromTaskId\":\"A\",\"toTaskId\":\"B\"},"
